import {messageMentionCandidates,messageHasBroadcastMention} from '<REPOSITORY>/packages/protocol/src/message-mention.ts';
export function canonical(s){
 if(messageHasBroadcastMention(s.message))return 'both';
 const mentions=messageMentionCandidates(s.message,s.members.map(m=>m.handle));
 const ids=s.members.filter(m=>m.id!==s.author.id&&mentions.some(x=>x.handle===m.handle)).map(m=>m.id).sort();
 return ids.length===2?'both':ids[0]??'none';
}
export function validateAnswer(a){if(!a||!['B','C','both','none','uncertain'].includes(a.choice)||!Number.isFinite(a.confidence)||a.confidence<0||a.confidence>1)throw Error('invalid-answer');return a;}
export function decision(s,a){const fixed=canonical(s);if(fixed!=='none')return fixed;if(!a)return 'none';validateAnswer(a);return a.confidence>=.9&&['B','C','both'].includes(a.choice)?a.choice:'none';}
// Small predeclared lexical comparator, not a proposal to ship this heuristic.
export function lexical(s){const fixed=canonical(s);if(fixed!=='none')return fixed;if(/不要|不用|无需|不需要|历史|昨天|之前|示例|引用|等待|如果|若|未来|明天|等.*再|已经结束|存档/u.test(s.message))return 'none';const ids=s.members.filter(m=>s.message.includes('请 '+m.handle)||s.message.includes('请'+m.handle)||s.message.includes(m.handle+', please')||s.message.includes(m.handle+'，核对')).map(m=>m.id);return ids.length===2?'both':ids[0]??'none';}
export function metrics(rows){const actionable=rows.filter(r=>['B','C','both'].includes(r.expected));return{n:rows.length,exact:rows.filter(r=>r.actual===r.expected).length,actionable:actionable.length,correctActionableRecall:actionable.length? actionablCorrect()/actionable.length:null,wrongWakes:rows.filter(r=>['B','C','both'].includes(r.actual)&&r.actual!==r.expected).length,abstentions:rows.filter(r=>r.actual==='none'||r.actual==='uncertain').length};function actionablCorrect(){return actionable.filter(r=>r.actual===r.expected).length;}}

