import test from 'node:test';
import assert from 'node:assert/strict';
import {decision,canonical,validateAnswer,metrics} from './eval.mjs';
const state={author:{id:'A',handle:'A'},members:[{id:'B',handle:'B'},{id:'C',handle:'C'}],message:'请 B 处理'};
test('no canonical mention does not invent an existing wake',()=>assert.equal(canonical(state),'none'));
test('explicit route cannot be vetoed',()=>assert.equal(decision({...state,message:'@B 处理'}, {choice:'none',confidence:1}),'B'));
test('low confidence abstains',()=>assert.equal(decision(state,{choice:'B',confidence:.89}),'none'));
test('certain selection routes',()=>assert.equal(decision(state,{choice:'B',confidence:.95}),'B'));
test('error and ambiguous response create no wake',()=>{assert.equal(decision(state,null),'none');assert.equal(decision(state,{choice:'uncertain',confidence:1}),'none')});
test('self and code mentions do not route',()=>{assert.equal(canonical({...state,message:'@A done'}),'none');assert.equal(canonical({...state,message:'`@B`'}),'none')});
test('invalid response fails closed',()=>{for(const a of [{choice:'D',confidence:1},{choice:'B',confidence:NaN},{choice:'B',confidence:1.1}])assert.throws(()=>validateAnswer(a))});
test('wrong recipient is both false positive and miss',()=>{const m=metrics([{expected:'B',actual:'C'}]);assert.equal(m.wrongWakes,1);assert.equal(m.correctActionableRecall,0)});

