import {readFileSync,writeFileSync,unlinkSync,existsSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {validateAnswer} from './eval.mjs';
const root=new URL('./',import.meta.url);const path=n=>new URL(n,root);
if(existsSync(path('started')))throw Error('Batch already started; no implicit paid rerun');
const plan=JSON.parse(readFileSync(path('plan.json'))),cases=JSON.parse(readFileSync(path('cases.json')));
if(cases.length!==240||plan.maxCalls!==240||plan.model!=='jev-1.13.0')throw Error('Plan mismatch');
const key=readFileSync(path('key'),'utf8').trim();unlinkSync(path('key'));
const hash=n=>createHash('sha256').update(readFileSync(path(n))).digest('hex');
writeFileSync(path('started'),JSON.stringify({at:new Date().toISOString(),hashes:Object.fromEntries(['plan.json','cases.json','eval.mjs','run.mjs'].map(n=>[n,hash(n)]))},null,2));
let next=0,stop=false;const results=[];
async function worker(){while(!stop&&next<cases.length){const c=cases[next++];const start=performance.now();let row;try{const r=await fetch('https://api.typesafe.ai/v1/systemone',{method:'POST',redirect:'error',headers:{Authorization:'Bearer '+key,'Content-Type':'application/json'},body:JSON.stringify({model:plan.model,state:c.state,questions:{route:{type:'choice',instructions:plan.instructions,criteria:plan.criteria}}}),signal:AbortSignal.timeout(plan.timeoutMs)});if(r.status!==200)throw Error('HTTP '+r.status);const body=await r.json();if(body.model!==plan.model)throw Error('Unexpected model');validateAnswer(body.answers?.route);row={id:c.id,ms:performance.now()-start,model:body.model,answer:body.answers.route,usage:body.usage};}catch(e){row={id:c.id,ms:performance.now()-start,error:String(e.message).replaceAll(key,'<redacted>')};stop=true;}results.push(row);writeFileSync(path('results.json'),JSON.stringify(results,null,2));if(results.length%20===0||row.error)console.log(JSON.stringify({completed:results.length,error:row.error}));}}
await Promise.all(Array.from({length:plan.maxConcurrency},worker));console.log(JSON.stringify({completed:results.length,stopped:stop}));

