import {readFileSync,writeFileSync} from 'node:fs';
import {decision,canonical,lexical,metrics} from './eval.mjs';
const root=new URL('./',import.meta.url),read=n=>JSON.parse(readFileSync(new URL(n,root)));
const cases=read('cases.json'),results=read('results.json'),plan=read('plan.json');
const rows=cases.map(c=>{const r=results.find(x=>x.id===c.id);return {...c,result:r,raw:r?.answer?.choice??'missing',hybrid:decision(c.state,r?.answer??null),canonical:canonical(c.state),lexical:lexical(c.state)}});
const summary={calls:results.length,errors:results.filter(r=>r.error).length,input:results.reduce((s,r)=>s+(r.usage?.input_tokens??0),0),output:results.reduce((s,r)=>s+(r.usage?.output_tokens??0),0),latency:{},splits:{},gate:plan.gate};
const latency=results.map(r=>r.ms).sort((a,b)=>a-b);summary.latency={p50:latency[Math.ceil(latency.length*.5)-1],p95:latency[Math.ceil(latency.length*.95)-1],max:latency.at(-1)};summary.estimatedUSD=summary.input*.042/1e6;
for(const split of ['development','holdout','all']){const selected=rows.filter(r=>split==='all'||r.split===split);summary.splits[split]=Object.fromEntries(['canonical','lexical','raw','hybrid'].map(arm=>[arm,metrics(selected.map(r=>({expected:r.expected,actual:r[arm]})))]));}
const h=summary.splits.holdout;
summary.pass=summary.errors===0&&h.hybrid.wrongWakes===0&&h.hybrid.correctActionableRecall>=.8&&h.raw.exact/h.raw.n>=.9;
summary.wrongAutomatic=rows.filter(r=>['B','C','both'].includes(r.hybrid)&&r.hybrid!==r.expected).map(r=>({id:r.id,split:r.split,message:r.state.message,expected:r.expected,actual:r.hybrid,confidence:r.result.answer.confidence}));
summary.rawWrong=rows.filter(r=>r.raw!==r.expected).map(r=>({id:r.id,split:r.split,message:r.state.message,expected:r.expected,actual:r.raw,confidence:r.result.answer.confidence}));
summary.missed=rows.filter(r=>r.split==='holdout'&&['B','C','both'].includes(r.expected)&&r.hybrid!==r.expected).map(r=>({id:r.id,expected:r.expected,actual:r.hybrid,raw:r.raw,confidence:r.result?.answer?.confidence}));
summary.familyCounts={development:20,holdout:40,total:60};
writeFileSync(new URL('summary.json',root),JSON.stringify(summary,null,2));console.log(JSON.stringify(summary,null,2));
